on\":false},{\"prepColumnName\":\"Future Unit Cost\",\"isUserCalculation\":false},{\"prepColumnName\":\"Base Cost\",\"isUserCalculation\":false},{\"prepColumnName\":\"Net Net Cost\",\"isUserCalculation\":false},{\"prepColumnName\":\"Dead Net Cost\",\"isUserCalculation\":false},{\"prepColumnName\":\"Acquisition Cost\",\"isUserCalculation\":false},{\"prepColumnName\":\"Pricing Cost\",\"isUserCalculation\":false},{\"prepColumnName\":\"Current Unit Cost\",\"isUserCalculation\":false},{\"prepColumnName\":\"Cost Change Amount\",\"isUserCalculation\":false},{\"prepColumnName\":\"Cost Change Percent\",\"isUserCalculation\":false},{\"prepColumnName\":\"System Cost Change\",\"isUserCalculation\":false},{\"prepColumnName\":\"Cost Change Direction\",\"isUserCalculation\":false},{\"prepColumnName\":\"Active Date\",\"isUserCalculation\":false},{\"prepColumnName\":\"End Date\",\"isUserCalculation\":false},{\"prepColumnName\":\"Days Until Effective\",\"isUserCalculation\":false},{\"prepColumnName\":\"Event Status Flag\",\"isUserCalculation\":false},{\"prepColumnName\":\"Franchise Pricing Flag\",\"isUserCalculation\":false},{\"prepColumnName\":\"Default Costing Type\",\"isUserCalculation\":false},{\"prepColumnName\":\"Primary Supplier Country Indicator\",\"isUserCalculation\":false},{\"prepColumnName\":\"Start Indicator\",\"isUserCalculation\":false},{\"prepColumnName\":\"Currency Code\",\"isUserCalculation\":false},{\"prepColumnName\":\"ELC Amount\",\"isUserCalculation\":false}],\"transforms\":[{\"id\":\"1\",\"type\":\"PROPERTY_CHANGE\",\"sourceColumns\":[\"Department Number\"],\"expressionSourceColumns\":[\"Department Number\"],\"outputColumns\":[],\"options\":{\"outputColumnAggrRule\":\"none\",\"outputColumnDisplayName\":\"Department Number\",\"outputColumnRole\":\"Attribute\",\"afterColumn\":\"Department Number\"},\"applied\":true,\"inplace\":true,\"rename\":false,\"allowEdit\":false,\"generatesOutputColumns\":false,\"unsavedTransform\":false,\"parentId\":null},{\"id\":\"2\",\"type\":\"PROPERTY_CHANGE\",\"sourceColumns\":[\"Class Number\"],\"expressionSourceColumns\":[\"Class Number\"],\"outputColumns\":[],\"options\":{\"outputColumnAggrRule\":\"none\",\"outputColumnDisplayName\":\"Class Number\",\"outputColumnRole\":\"Attribute\",\"afterColumn\":\"Class Number\"},\"applied\":true,\"inplace\":true,\"rename\":false,\"allowEdit\":false,\"generatesOutputColumns\":false,\"unsavedTransform\":false,\"parentId\":\"1\"},{\"id\":\"3\",\"type\":\"PROPERTY_CHANGE\",\"sourceColumns\":[\"Subclass Number\"],\"expressionSourceColumns\":[\"Subclass Number\"],\"outputColumns\":[],\"options\":{\"outputColumnAggrRule\":\"none\",\"outputColumnDisplayName\":\"Subclass Number\",\"outputColumnRole\":\"Attribute\",\"afterColumn\":\"Subclass Number\"},\"applied\":true,\"inplace\":true,\"rename\":false,\"allowEdit\":false,\"generatesOutputColumns\":false,\"unsavedTransform\":false,\"parentId\":\"2\"},{\"id\":\"4\",\"type\":\"PROPERTY_CHANGE\",\"sourceColumns\":[\"Supplier ID\"],\"expressionSourceColumns\":[\"Supplier ID\"],\"outputColumns\":[],\"options\":{\"outputColumnAggrRule\":\"none\",\"outputColumnDisplayName\":\"Supplier ID\",\"outputColumnRole\":\"Attribute\",\"afterColumn\":\"Supplier ID\"},\"applied\":true,\"inplace\":true,\"rename\":false,\"allowEdit\":false,\"generatesOutputColumns\":false,\"unsavedTransform\":false,\"parentId\":\"3\"},{\"id\":\"5\",\"type\":\"PROPERTY_CHANGE\",\"sourceColumns\":[\"Location ID\"],\"expressionSourceColumns\":[\"Location ID\"],\"outputColumns\":[],\"options\":{\"outputColumnAggrRule\":\"none\",\"outputColumnDisplayName\":\"Location ID\",\"outputColumnRole\":\"Attribute\",\"afterColumn\":\"Location ID\"},\"applied\":true,\"inplace\":true,\"rename\":false,\"allowEdit\":false,\"generatesOutputColumns\":false,\"unsavedTransform\":false,\"parentId\":\"4\"}],\"recommendations\":[],\"dataSubsetInfos\":{\"queryEditMode\":1,\"filterbarSettings\":{},\"uiSqlStatement\":\"

-- ── Query 3 ────────────────────────────────────────────────────────────
SELECT\\n    TRUNC(SYSDATE)                                        AS \\\"Report Date\\\",\\n    fc.ITEM                                               AS \\\"Item ID\\\",\\n    im.ITEM_DESC                                          AS \\\"Item Description\\\",\\n    im.DEPT                                               AS \\\"Department Number\\\",\\n    d.DEPT_NAME                                           AS \\\"Department Name\\\",\\n    im.CLASS                                              AS \\\"Class Number\\\",\\n    c.CLASS_NAME                                          AS \\\"Class Name\\\",\\n    im.SUBCLASS                                           AS \\\"Subclass Number\\\",\\n    sc.SUB_NAME                                           AS \\\"Subclass Name\\\",\\n    fc.SUPPLIER                                           AS \\\"Supplier ID\\\",\\n    sp.SUP_NAME                                           AS \\\"Supplier Name\\\",\\n    sp.SUP_STATUS                                         AS \\\"Supplier Status\\\",\\n    fc.ORIGIN_COUNTRY_ID                                  AS \\\"Origin Country ID\\\",\\n    fc.LOCATION                                           AS \\\"Location ID\\\",\\n    fc.LOC_TYPE                                           AS \\\"Location Type\\\",\\n    CASE fc.LOC_TYPE\\n        WHEN 'S' THEN st.STORE_NAME\\n        WHEN 'W' THEN wh.WH_NAME\\n        ELSE TO_CHAR(fc.LOCATION)\\n    END                                                   AS \\\"Location Name\\\",\\n    fc.NET_COST                                           AS \\\"Future Unit Cost\\\",\\n    fc.BASE_COST                                          AS \\\"Base Cost\\\",\\n    fc.NET_NET_COST                                       AS \\\"Net Net Cost\\\",\\n    fc.DEAD_NET_NET_COST                                  AS \\\"Dead Net Cost\\\",\\n    fc.ACQUISITION_COST                                   AS \\\"Acquisition Cost\\\",\\n    fc.PRICING_COST                                       AS \\\"Pricing Cost\\\",\\n    isc.UNIT_COST                                         AS \\\"Current Unit Cost\\\",\\n    ROUND(fc.NET_COST - NVL(isc.UNIT_COST, 0), 4)        AS \\\"Cost Change Amount\\\",\\n    CASE\\n        WHEN NVL(isc.UNIT_COST, 0) &gt; 0\\n        THEN ROUND((fc.NET_COST - NVL(isc.UNIT_COST, 0))\\n                   / isc.UNIT_COST * 100, 2)\\n    END                                                   AS \\\"Cost Change Percent\\\",\\n    fc.COST_CHANGE                                        AS \\\"System Cost Change\\\",\\n    CASE\\n        WHEN fc.NET_COST &gt; NVL(isc.UNIT_COST, 0) THEN 'INCREASE'\\n        WHEN fc.NET_COST &lt; NVL(isc.UNIT_COST, 0) THEN 'DECREASE'\\n        WHEN fc.NET_COST = NVL(isc.UNIT_COST, 0) THEN 'NO CHANGE'\\n        ELSE 'CURRENT COST UNKNOWN'\\n    END                                                   AS \\\"Cost Change Direction\\\",\\n    fc.ACTIVE_DATE                                        AS \\\"Active Date\\\",\\n    fc.CALC_DATE                                          AS \\\"End Date\\\",\\n    fc.ACTIVE_DATE - TRUNC(SYSDATE)                       AS \\\"Days Until Effective\\\",\\n    CASE\\n        WHEN fc.ACTIVE_DATE &lt; TRUNC(SYSDATE)\\n        THEN 'ACTIVE - Cost change is live'\\n        WHEN fc.ACTIVE_DATE = TRUNC(SYSDATE)\\n        THEN 'EFFECTIVE TODAY'\\n        WHEN fc.ACTIVE_DATE &gt; TRUNC(SYSDATE)\\n        THEN 'FUTURE - Pending effective date'\\n        ELSE 'REVIEW'\\n    END                                                   AS \\\"Event Status Flag\\\",\\n    CASE\\n        WHEN NVL(fc.PRICING_COST, 0) != NVL(fc.NET_COST, 0)\\n             AND fc.PRICING_COST IS NOT NULL\\n        THEN 'YES - Franchise Pricing Cost differs from Net Cost'\\n        ELSE 'NO'\\n    END                                                   AS \\\"Franchise Pricing Flag\\\",\\n    fc.DEFAULT_COSTING_TYPE                               AS \\\"Default Costing Type\\\",\\n    fc.PRIMARY_SUPP_COUNTRY_IND                           AS \\\"Primary Supplier Country Indicator\\\",\\n    fc.START_IND                                          AS \\\"Start Indicator\\\",\\n    fc.CURRENCY_CODE                                      AS \\\"Currency Code\\\",\\n    fc.ELC_AMT                                            AS \\\"ELC Amount\\\"\\nFROM\\n    MFCS_RDS.RDS_WV_FUTURE_COST              fc\\n    JOIN  MFCS_RDS.RDS_WV_ITEM_MASTER        im   ON  fc.ITEM       = im.ITEM\\n    JOIN  MFCS_RDS.RDS_WV_DEPS               d    ON  im.DEPT       = d.DEPT\\n    JOIN  MFCS_RDS.RDS_WV_CLASS              c    ON  im.DEPT       = c.DEPT\\n                                                  AND  im.CLASS      = c.CLASS\\n    JOIN  MFCS_RDS.RDS_WV_SUBCLASS           sc   ON  im.DEPT       = sc.DEPT\\n                                                  AND  im.CLASS      = sc.CLASS\\n                                                  AND  im.SUBCLASS   = sc.SUBCLASS\\n    LEFT JOIN MFCS_RDS.RDS_WV_SUPS           sp   ON  fc.SUPPLIER   = sp.SUPPLIER\\n    LEFT JOIN MFCS_RDS.RDS_WV_STORE          st   ON  fc.LOCATION   = st.STORE\\n    LEFT JOIN MFCS_RDS.RDS_WV_WH             wh   ON  fc.LOCATION   = wh.WH\\n    LEFT JOIN (\\n

-- ── Query 4 ────────────────────────────────────────────────────────────
SELECT ITEM, SUPPLIER, UNIT_COST\\n        FROM   MFCS_RDS.RDS_WV_ITEM_SUPP_COUNTRY\\n        WHERE  PRIMARY_SUPP_IND    = 'Y'\\n        AND    PRIMARY_COUNTRY_IND = 'Y'\\n    )                                        isc  ON  fc.ITEM       = isc.ITEM\\n                                                  AND  fc.SUPPLIER   = isc.SUPPLIER\\nWHERE\\n    fc.ACTIVE_DATE &gt;= ADD_MONTHS(SYSDATE, -3)\"},\"editorCurrentState\":false,\"joins\":{\"tables\":[]}}</ds:uiOptions><ds:version>v5</ds:version></ds:datasetImportOptions>","business-model":"\"\"","active":true,"custom-attrs":"{\"src_parquet_verified\":\"true\"}","description":"External dataset","display-name":"Manual Query","locale":"sys","is-user-striped":false,"file-length":0,"type":"sql","properties-last-modified":"2026-08-03T04:46:01.200+0000","connection-namespace":"disadmin_disadmin_APPID","private-connection":false,"credential-exists":true,"connection-name":"Remote RDS MFCS Connection","provider-type":"db","provider-name":"oracle","sso-enabled":false,"datamodelname":"'ReCommon'.'RPT_042_Cost_Event_Details'","parent-namespace":"ReCommon","parent-name":"RPT_042_Cost_Event_Details","data-access-mode":"auto","is-data-cacheable":true,"checkpoint-metadata-stale":false,"owner-guid":"ReCommon","is-temporary":false},"datasetType":"EMBEDDED","datamodelTwoPartName":"'ReCommon'.'RPT_042_Cost_Event_Details'"}
